    java.util.Map<String, Object> yamlControl = new java.util.LinkedHashMap<>();
    String yamlControlValue = new String(new int[] { 0x0001, 0x0008, 0x000c, 0x1f642 }, 0, 4);
    yamlControl.put("value", yamlControlValue);
    String yamlControlText = TypraYaml.stringify(yamlControl);
    assertTrue(yamlControlText.contains("\\u0001"), "YAML should unicode-escape C0 controls");
    assertTrue(yamlControlText.contains("\\b"), "YAML should escape backspace");
    assertTrue(yamlControlText.contains("\\f"), "YAML should escape form feed");
    Object yamlParsed = TypraYaml.parse("value: \"\\b\\f\\u0001\\uD83D\\uDE42\"");
    Object yamlValue = ((java.util.Map<?, ?>) yamlParsed).get("value");
    String yamlParsedExpected = new String(new int[] { 0x0008, 0x000c, 0x0001, 0x1f642 }, 0, 4);
    assertEquals(yamlParsedExpected, yamlValue, "YAML should decode named and unicode escapes");
    assertThrows(() -> TypraYaml.parse("value: \"\\x\""), "YAML should reject unknown escapes");
